import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { Script, createContext } from 'node:vm';
import { test } from 'node:test';

const read = file => readFile(new URL('../' + file, import.meta.url), 'utf8');
const pkg = JSON.parse(await read('package.json'));
const artifact = await read(pkg.exports['./client']);
const author = await read('client.js');

test('manifest ships a local single-registration browser bundle synchronized with the client source', () => {
  assert.equal(pkg.exports['./client'], './client.bundle.js');
  assert(pkg.files.includes('client.bundle.js'));
  assert.equal(pkg.dependencies, undefined, 'Runtime install needs no external editor dependencies');
  assert(artifact.endsWith('\n' + author + '\n})();\n'));
  assert(artifact.startsWith(`/* Generated by editor-build/build-client.mjs; client.js sha256 ${createHash('sha256').update(author).digest('hex')}. */`));
  const registrations = [];
  const world = createContext({ window: { __ModuleLoader__: { load(spec) { registrations.push(spec); } } } });
  new Script(artifact, { filename: pkg.exports['./client'] }).runInContext(world, { timeout: 4000 });
  assert.equal(registrations.length, 1);
  assert.equal(registrations[0].id, pkg.name);
  assert.equal(typeof registrations[0].factory, 'function');
  assert.deepEqual(Object.keys(world), ['window'], 'Evaluation does not leak an editor global or access a DOM/browser runtime');
});
